  heif_chroma_monochrome=0,
  heif_chroma_420=1,
  heif_chroma_422=2,
  heif_chroma_444=3,
  heif_chroma_interleaved_RGB =10,
  heif_chroma_interleaved_RGBA=11,
  heif_chroma_interleaved_RRGGBB_BE  =12,
  heif_chroma_interleaved_RRGGBBAA_BE=13,
